    """Return a list of (tier_index, value) tuples for all keyword-matched candidates.

    Candidates from lower tier_index (higher priority) come first. Within a tier they
    are ordered from LAST match to FIRST match (final total tends to appear last).
    """
    lines = [ln.rstrip() for ln in text.splitlines()]
    summary_start = find_summary_start(lines)
    out = []

    for tier_idx, tier in enumerate(PRIORITY_TIERS):
        matches = []
        for i, line in enumerate(lines[:summary_start]):
            if is_excluded(line):
                continue
            if any(kw.search(line) for kw in tier):
                matches.append(i)
        for i in reversed(matches):
            val = extract_last_number(lines[i])
            if val is not None:
                out.append((tier_idx, val))
                continue
            # Split-line fallback for pure-keyword lines only.
            if any(c.isdigit() for c in lines[i]):
                continue
            for j in range(i + 1, min(i + 3, len(lines))):
                if not lines[j].strip():
                    continue
                if is_excluded(lines[j]):
                    break
                v = extract_last_number(lines[j])
                if v is not None:
                    out.append((tier_idx, v))
